CustomField.formula:
IF( TEXT(LearnerAccount.Student_Type__c) = "Returning", TRUE,
AND( /* Must contain "Verified" */ CONTAINS(TEXT(Birth_Certificate__c), "Verified"), CONTAINS(TEXT(Physical_Upload__c), "Verified"), CONTAINS(TEXT(Immunization_Records__c), "Verified"), CONTAINS(TEXT(Parent_Contract__c), "Verified"), CONTAINS(TEXT(Student_Info_Contact_Form__c), "Verified"), CONTAINS(TEXT(Housing_Questionnaire__c), "Verified"), CONTAINS(TEXT(FERPA_Directory_Info_Notice__c), "Verified"), CONTAINS(TEXT(TELA_Fee_Verification__c), "Verified"), CONTAINS(TEXT(Media_Photo_Release__c), "Verified"),
/* Verified OR N/A */ OR(CONTAINS(TEXT(Pre_K_Flu_Shot_Form__c), "Verified"), CONTAINS(TEXT(Pre_K_Flu_Shot_Form__c), "N/A")), OR(CONTAINS(TEXT(MAF_Upload__c), "Verified"), CONTAINS(TEXT(MAF_Upload__c), "N/A")), OR(CONTAINS(TEXT(Uploaded_IEP__c), "Verified"), CONTAINS(TEXT(Uploaded_IEP__c), "N/A")), OR(CONTAINS(TEXT(Overnight_Trip_Form__c), "Verified"), CONTAINS(TEXT(Overnight_Trip_Form__c), "N/A")), OR(CONTAINS(TEXT(Proof_of_NYS_Residency_1__c), "Verified"), CONTAINS(TEXT(Proof_of_NYS_Residency_1__c), "N/A")), OR(CONTAINS(TEXT(Proof_of_NYS_Residency_2__c), "Verified"), CONTAINS(TEXT(Proof_of_NYS_Residency_2__c), "N/A")), OR(CONTAINS(TEXT(Proof_of_NYS_Residency_3__c), "Verified"), CONTAINS(TEXT(Proof_of_NYS_Residency_3__c), "N/A")), OR(CONTAINS(TEXT(Home_Language_Questionnaire__c), "Verified"), CONTAINS(TEXT(Home_Language_Questionnaire__c), "N/A")), OR(CONTAINS(TEXT(Activities_Field_Trip_Consent_Form__c), "Verified"), CONTAINS(TEXT(Activities_Field_Trip_Consent_Form__c), "N/A")), OR(CONTAINS(TEXT(Consent_to_Release_Student_Records__c), "Verified"), CONTAINS(TEXT(Consent_to_Release_Student_Records__c), "N/A")), OR(CONTAINS(TEXT(Computer_Tablet_Use_Consent_Form__c), "Verified"), CONTAINS(TEXT(Computer_Tablet_Use_Consent_Form__c), "N/A")), OR(CONTAINS(TEXT(Laptop_Tablet_Agreement__c), "Verified"), CONTAINS(TEXT(Laptop_Tablet_Agreement__c), "N/A")), OR(CONTAINS(TEXT(Ethnic_Identification_Form__c), "Verified"), CONTAINS(TEXT(Ethnic_Identification_Form__c), "N/A")),
/* HLQ + ATS */ CONTAINS(Housing_ATS_Code__c, "("), NOT(INCLUDES(Language_s_on_HLQ__c, "Not yet done")),
/* Ethnicity and Race */ OR(CONTAINS(TEXT(Ethnicity_Answer__c), "Hispanic"), CONTAINS(TEXT(Ethnicity_Answer__c), "N/A")), OR( CONTAINS(TEXT(Race_Answers__c), "B"), CONTAINS(TEXT(Race_Answers__c), "C"), CONTAINS(TEXT(Race_Answers__c), "D"), CONTAINS(TEXT(Race_Answers__c), "E"), CONTAINS(TEXT(Race_Answers__c), "F"), CONTAINS(TEXT(Race_Answers__c), "N/A") ),
/* Family Decision logic */ OR( CONTAINS(TEXT(Family_Decision__c), "Accept"), AND( CONTAINS(TEXT(Family_Decision__c), "N/A"), OR(TEXT(Grade_Applied__c) = "K", TEXT(Grade_Applied__c) = "1") ) ) ) )
